-- Price change approval: MULTI-SITE (slug: price-change).
--
-- Replaces the single-site draft with one where the grid collects its own
-- sites, so a regional change is one request and one approval. All or nothing:
-- Dan approves or denies the whole request.
--
-- REMOVES the site_number and site_name fields. Submissions on this version
-- are therefore NOT location-scoped: site staff cannot see them, by design --
-- only admins and the workflow's own people. forms.scope_location_field_key
-- stays 'site_number' on purpose; clearing it would make the next publish
-- re-inject a site_number field.
--
-- Existing single-site submissions keep their own schema version and render
-- exactly as before.
--
-- Generated by scripts/gen-price-change.ts (approver: Dan Petrelle):
--   cd packages/forms-schema && npx tsx ../../scripts/gen-price-change.ts out.json
-- For a test run, set APPROVER=<your address> when generating instead.
--
-- Updates the DRAFT only. Publishing it in the builder is what makes it live.
-- SAFE TO RE-RUN.

update public.forms
   set description = 'Request a package price change at one or more sites. Add each site, tick the packages that are changing, and enter their current and new prices.',
       last_edited_at = now()
 where slug = 'price-change';

update public.form_versions v
   set schema = '{"fields":[{"key":"packages","id":"41a6ed19","type":"package_price_grid","label":"Sites and packages","required":true,"multiSite":true,"keyFieldKey":"","keyColumn":"pricing_simple.site","show_in_queue":true,"helpText":"Add each site by its 3-digit number, then tick the packages changing there. Enter current prices as they are today; leave a new price blank if it isn''t changing."},{"key":"notes","id":"3c026dd7","type":"long_text","label":"Notes for the approver","required":false,"maxLength":2000,"helpText":"Optional: reason for the change, timing, anything Dan should know."}],"workflow":{"default_stage":"notify_dan","stages":[{"id":"notify_dan","label":"Email Dan","kind":"email","recipients":[{"type":"static_emails","emails":["dpetrelle@splashcarwashes.com"]}],"subject_template":"Price change approval needed: {field.packages.sites}","body_template":"{submitter.email} has requested a price change at {field.packages.sites}.\n\n{payload.summary}\n\n{approval.link}\n\nThe link works without signing in and expires in 7 days. Approving needs your signature; denying needs a short note.","transitions":[{"to":"dan_review","label":"Sent"}]},{"id":"dan_review","label":"Dan''s approval","kind":"approval","approver_source":{"type":"static_emails","emails":["dpetrelle@splashcarwashes.com"]},"transitions":[{"to":"approved_email","label":"Approve","requires":{"signature":true}},{"to":"denied_email","label":"Deny","requires":{"note":true}}]},{"id":"approved_email","label":"Email approval","kind":"email","recipients":[{"type":"payload_field","field_key":"submitter.email"}],"attach_pdf":true,"subject_template":"Approved: price change at {field.packages.sites}","body_template":"Your price change request for {field.packages.sites} was {outcome.label} by {decision.by}.\n\n{payload.summary}\n\nThe signed approval is attached. Prices have not been changed yet; this records the approval only.\n\n{submission.url}","transitions":[{"to":"approved","label":"Sent"}]},{"id":"denied_email","label":"Email denial","kind":"email","recipients":[{"type":"payload_field","field_key":"submitter.email"}],"attach_pdf":true,"subject_template":"Denied: price change at {field.packages.sites}","body_template":"Your price change request for {field.packages.sites} was {outcome.label} by {decision.by}.\n\nReason: {decision.note}\n\n{payload.summary}\n\n{submission.url}","transitions":[{"to":"denied","label":"Sent"}]},{"id":"approved","label":"Approved","kind":"outcome","tint":"success","transitions":[]},{"id":"denied","label":"Denied","kind":"outcome","tint":"danger","transitions":[]}]}}'::jsonb
  from public.forms f
 where f.slug = 'price-change' and v.id = f.draft_version_id;

select f.slug, f.status, v.version_number as draft_version,
       jsonb_array_length(v.schema->'fields') as fields,
       (v.schema->'fields'->0->>'multiSite') as multi_site,
       (select s->'approver_source'->'emails'->>0
          from jsonb_array_elements(v.schema->'workflow'->'stages') s
         where s->>'id' = 'dan_review') as approver
  from public.forms f
  join public.form_versions v on v.id = f.draft_version_id
 where f.slug = 'price-change';
